> hit hide on the domains that I never want to see anything from You could convert this into content blocker filters for the likes of uBlock Origin: news.ycombinator.com##.submission:has([href^="https://example.com/"]),.submission:has([href^="https://example.com/"])+tr,.submission:has([href^="https://example.com/"])+tr+.spacer (You can append `:style(color:orange)` or such to apply a different style instead of hiding, if you want to be able to hit the hide link in order to get a new thirtieth item—though you could automate that by writing a user script instead.) Or user stylesheets (I use Stylus in Firefox to manage such things): .submission:has([href="from?site=example.com"]) {
      &, & + tr, & + tr + .spacer {
          display: none;
      }
  } (I showed two different selectors: [href^=" https://example.com/ "] will match the complete origin, [href="from?site=example.com"] will match the domain as presented by HN, including any subdomains.) reply

I use the bookmarklet below. It jumps to the newest story on the frontpage. And when I click the bookmarklet again (or press "n") it jumps to the next. So I just click it until I land on a story I have already seen and know I have seen them all. If you want to use it, you can convert the code into a bookmarklet with my bookmarklet editor: https://www.gibney.org/bookmarklet_editor The bookmarklet: if (!location.href.match('ycom'))
        location.href='https://news.ycombinator.com';

    doTheMagic = function() {
        if (typeof e!=='undefined')
            e.style.background='#c0c0c0';
        e=Array.from(
            document.querySelectorAll(
                '.age a:not(.seen)')
        ).sort().at(-1);
        e.style.background='#ff0';
        e.classList.add('seen');
        e.scrollIntoView({
            behavior:"smooth",
            block:"center",
            inline:"nearest"
        });
    }

    function addShortcuts() {
        document.addEventListener("keydown", function(evnt) {
            if (evnt.key === "n") doTheMagic();
        });
    }

    function addStyle() {
       let style = document.createElement('style');
        style.type = 'text/css';
        style.textContent = `
            .noshow {
                display: initial;
            }
        `;
        document.head.appendChild(style);
    }

    if (typeof theMagicIsActive=='undefined') {
        addShortcuts();
        addStyle();
        theMagicIsActive = true;
    }

    doTheMagic(); reply
